26	function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }
27	async function waitIce() {
28	  const t0 = Date.now();
29	  while (pc.iceGatheringState !== 'complete' && Date.now() - t0 < 6000) await sleep(100);
